solutions = []
for x0 in range(7):
    for x1 in range(7):
        for x2 in range(7):
            for x3 in range(7):
                for x4 in range(7):
                    for x5 in range(7):
                        seq = [x0, x1, x2, x3, x4, x5]
                        if sum(seq) != 6:
                            continue
                        # Check if each x[i] equals count of i in seq
                        valid = True
                        for i in range(6):
                            if seq.count(i) != seq[i]:
                                valid = False
                                break
                        if valid:
                            solutions.append(seq)

print("Solutions found:", len(solutions))
for sol in solutions:
    print(sol)
